function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 50) return 'nums needs 1 to 50 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1e9)) return 'Each value is an integer from 1 to 10^9.';
  if (!Number.isInteger(k) || k < 1 || k > 1e9) return 'k is an integer from 1 to 10^9.';
  if (!nums.some(v => v >= k)) return 'At least one value must be >= k.';
  return null;
}

