function generate(rand, size) {
  const n = size === 'large' ? 50 : 1 + Math.floor(rand() * 8);
  const top = size === 'large' ? 1e9 : 12;
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  const k = 1 + Math.floor(rand() * top);
  // Guarantee at least one value reaches k by raising one random position.
  if (!nums.some(v => v >= k)) nums[Math.floor(rand() * n)] = k + Math.floor(rand() * (top - k + 1));
  return [nums, k];
}
